package com.resolvenow.assignment;
import org.springframework.stereotype.Service; import java.util.*;
@Service public class AssignmentService { private final AssignmentRepository repository; private final NotificationClient notificationClient; public AssignmentService(AssignmentRepository repository,NotificationClient notificationClient){this.repository=repository;this.notificationClient=notificationClient;} public List<Assignment> all(){return repository.findAll();} public Assignment assign(Long complaintId,String recipient,String department,String agent){Assignment saved=repository.save(new Assignment(complaintId,department,agent)); try{notificationClient.notify(new NotificationClient.NotificationRequest(complaintId,recipient,"Complaint assigned to "+department+" / "+agent));}catch(RuntimeException ignored){} return saved;} }
